/*\
title: $:/plugins/huwiki/ai/model-capabilities.js
type: application/javascript
module-type: library

Conservative client-side model capability hints. Not a guarantee of API access.
\*/
(function(){
"use strict";
function textChat(provider,name){
  var s=String(name||"").toLowerCase();
  if(!s || /moderation|embedding|embed-|rerank|whisper|transcrib|tts|speech|audio-only|image-gen|dall-e|gpt-image|imagen|veo/.test(s))return false;
  if(provider==="gemini")return /gemini/.test(s) && !/embedding|tts|audio-only/.test(s);
  if(provider==="openai")return /gpt-|o[1-9](?:-|$)|chatgpt/.test(s);
  if(provider==="claude")return /claude/.test(s);
  return true;
}
function vision(provider,name){
  var s=String(name||"").toLowerCase();
  if(!textChat(provider,name))return false;
  // Only well-established vision families. Providers can change capabilities.
  if(provider==="gemini")return /gemini-(?:1\.5|2\.|3\.|4\.)/.test(s);
  if(provider==="openai")return /gpt-(?:4o|4\.1|4\.5|5|6)|chatgpt-4o/.test(s);
  if(provider==="claude")return /claude-(?:3|4)/.test(s);
  return /gemma[-:]?4|llava|qwen(?:2\.5|3)[-_]?vl|pixtral|vision|llama3\.2.*vision|mistral-small-3\.2/i.test(s);
}
function available(models,provider,task){
  return (Array.isArray(models)?models:[]).filter(function(name){return task==="vision"?vision(provider,name):textChat(provider,name);});
}
exports.vision=vision;exports.textChat=textChat;exports.available=available;
})();
